import{b as a,O as d,g as e,j as s}from"./chunks/framework.DcaUmd3X.js";const o="/assets/image.D1SigDRu.webp",g=JSON.parse('{"title":"MySQL简介","description":"","frontmatter":{},"headers":[],"relativePath":"database/mysql/pre/intro/index.md","filePath":"数据库管理/MySQL必知必会/1.开篇/01.MySQL简介.md","lastUpdated":1783947942000}'),r={name:"database/mysql/pre/intro/index.md"};function i(l,t,n,h,p,c){return d(),e("div",null,[...t[0]||(t[0]=[s('<h1 id="mysql简介" tabindex="-1">MySQL简介 <a class="header-anchor" href="#mysql简介" aria-label="Permalink to &quot;MySQL简介&quot;">​</a></h1><blockquote><p>什么是MySQL？为什么要用数据库？怎么工作？</p></blockquote><h2 id="什么是-mysql" tabindex="-1">什么是 MySQL <a class="header-anchor" href="#什么是-mysql" aria-label="Permalink to &quot;什么是 MySQL&quot;">​</a></h2><p>MySQL 是一个 <strong>开源的关系型数据库管理系统（RDBMS）</strong>，由瑞典 MySQL AB 公司开发，目前属于 Oracle 公司旗下。</p><p>简单说，MySQL 就是一个<strong>存储和管理数据的软件</strong>。你在网站上注册的账号、购物车里的商品、朋友圈的动态——这些数据大概率都存在某个 MySQL 数据库里。</p><h2 id="为什么要用数据库" tabindex="-1">为什么要用数据库？ <a class="header-anchor" href="#为什么要用数据库" aria-label="Permalink to &quot;为什么要用数据库？&quot;">​</a></h2><p>你可能会想：用 Excel 存数据不也挺好吗？</p><p>对于少量数据确实没问题，但当数据量变大、场景变复杂时，数据库的优势就出来了：</p><table tabindex="0"><thead><tr><th>场景</th><th>Excel</th><th>MySQL</th></tr></thead><tbody><tr><td>存 100 行数据</td><td>✅ 没问题</td><td>✅ 没问题</td></tr><tr><td>存 1000 万行数据</td><td>❌ 卡到怀疑人生</td><td>✅ 轻松应对</td></tr><tr><td>同时有 100 个人读写</td><td>❌ 不支持</td><td>✅ 原生支持并发</td></tr><tr><td>精确控制谁能改什么数据</td><td>❌ 基本靠吼</td><td>✅ 细粒度权限管理</td></tr><tr><td>数据误删了想撤回</td><td>❌ 找不回来</td><td>✅ 事务回滚</td></tr><tr><td>按复杂条件查数据</td><td>手动筛选，累</td><td>一句 SQL 搞定</td></tr></tbody></table><blockquote><p>💡 <strong>一句话总结</strong>：少量数据自己玩用 Excel 就行，正经项目老老实实用数据库。</p></blockquote><h2 id="mysql-是怎么工作的" tabindex="-1">MySQL 是怎么工作的？ <a class="header-anchor" href="#mysql-是怎么工作的" aria-label="Permalink to &quot;MySQL 是怎么工作的？&quot;">​</a></h2><p>MySQL 采用的是<strong>客户端—服务器</strong>架构，打个比方：</p><p><img src="'+o+`" alt="alt text"></p><ul><li><strong>客户端</strong>：你敲命令的地方——可能是黑框终端（mysql命令行），也可能是图形界面（MySQL Workbench、Navicat、DataGrip）</li><li><strong>服务器</strong>：真正干活的那个后台程序（<code>mysqld</code>），负责解析你的 SQL、读写磁盘上的数据、管理并发访问</li></ul><p>你平时捣鼓 MySQL 的时候，就是客户端和服务器在对话——你写一句 SQL，服务器理解后执行，然后把结果返回给你。</p><h2 id="sql-是什么" tabindex="-1">SQL 是什么？ <a class="header-anchor" href="#sql-是什么" aria-label="Permalink to &quot;SQL 是什么？&quot;">​</a></h2><p>SQL（Structured Query Language，结构化查询语言）就是<strong>你和 MySQL 对话的语言</strong>。</p><p>比如你想查&quot;所有姓张的用户&quot;，用 SQL 写就是：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> users </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> name</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> LIKE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;张%&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>MySQL 看不懂中文，但它看得懂 SQL。学 MySQL 的本质，就是学 SQL。</p><h2 id="sql-分四类" tabindex="-1">SQL 分四类 <a class="header-anchor" href="#sql-分四类" aria-label="Permalink to &quot;SQL 分四类&quot;">​</a></h2><p>SQL 命令虽然多，但可以分成四大类。后面的教程你会逐类学完：</p><table tabindex="0"><thead><tr><th>分类</th><th>全称</th><th>干什么</th><th>包含的命令</th></tr></thead><tbody><tr><td><strong>DML</strong></td><td>数据操纵语言</td><td>对数据增删改查</td><td><code>SELECT</code>、<code>INSERT</code>、<code>UPDATE</code>、<code>DELETE</code></td></tr><tr><td><strong>DDL</strong></td><td>数据定义语言</td><td>定义表结构</td><td><code>CREATE</code>、<code>ALTER</code>、<code>DROP</code>、<code>TRUNCATE</code></td></tr><tr><td><strong>DCL</strong></td><td>数据控制语言</td><td>控制谁可以访问</td><td><code>GRANT</code>、<code>REVOKE</code></td></tr><tr><td><strong>TCL</strong></td><td>事务控制语言</td><td>控制事务</td><td><code>COMMIT</code>、<code>ROLLBACK</code>、<code>SAVEPOINT</code></td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>学 SQL 的路线就是这四类逐个击破：</span></span>
<span class="line"><span>DML（查数据）→ DDL（建表）→ TCL（事务）→ DCL（权限）</span></span></code></pre></div><p>这份教程也是按这个顺序安排的——先教你查数据，再建表，最后学事务和安全。</p><blockquote><p>💡 面试常问：&quot;SQL 分哪几类？&quot;记住 DML、DDL、DCL、TCL 四个缩写就行。</p></blockquote><h2 id="mysql-的特点" tabindex="-1">MySQL 的特点 <a class="header-anchor" href="#mysql-的特点" aria-label="Permalink to &quot;MySQL 的特点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>特性</th><th>说明</th></tr></thead><tbody><tr><td>开源免费</td><td>社区版完全免费，企业版提供额外功能</td></tr><tr><td>跨平台</td><td>支持 Windows、Linux、macOS 等多种操作系统</td></tr><tr><td>高性能</td><td>采用 B+ 树索引引擎，查询速度快</td></tr><tr><td>多存储引擎</td><td>支持 InnoDB、MyISAM、Memory 等多种存储引擎</td></tr><tr><td>事务支持</td><td>InnoDB 引擎支持 ACID 事务</td></tr><tr><td>安全性高</td><td>提供用户权限管理、SSL 加密等安全机制</td></tr><tr><td>可扩展性</td><td>支持分区表、主从复制、读写分离等高可用方案</td></tr></tbody></table><h2 id="常见版本" tabindex="-1">常见版本 <a class="header-anchor" href="#常见版本" aria-label="Permalink to &quot;常见版本&quot;">​</a></h2><ul><li><strong>MySQL 5.7</strong>：经典稳定版，仍被大量企业使用（但官方已停止更新支持）</li><li><strong>MySQL 8.0</strong>：当前主流版本，引入了窗口函数、CTE、JSON 增强等特性</li><li><strong>MySQL 8.4+</strong>：最新 LTS（长期支持）版本</li></ul><blockquote><p>💡 <strong>学习建议</strong>：新手直接学 MySQL 8.0 起步即可。8.0 是现在的绝对主流，文中所有示例也都基于 8.0。</p></blockquote><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>这章就记住三件事：</p><ol><li><strong>MySQL 是存数据的仓库</strong>——你注册的账号、下的订单、发的动态都在里面</li><li><strong>SQL 是你和 MySQL 对话的语言</strong>——你写 SQL，它执行，返回结果</li><li><strong>客户端发请求，服务器干活的架构</strong>——你敲命令的地方是客户端，后台跑着的是服务器</li></ol><p>一句话：<strong>学 MySQL = 学怎么用 SQL 操作数据</strong>。下一章把环境搭起来，就可以开始动手了。</p>`,35)])])}const S=a(r,[["render",i]]);export{g as __pageData,S as default};
